from collections import Counter
from typing import List, Tuple


def digits(b: int, n: int) -> List[int]:
    out: List[int] = []
    while n > 0:
        out.append(n % b)
        n //= b
    return out


def is_fang_pair(b: int, x: int, y: int) -> bool:
    """Digits of x*y are a permutation of digits(x) ++ digits(y)."""
    return Counter(digits(b, x * y)) == Counter(digits(b, x)) + Counter(digits(b, y))


def vampires_below(limit: int) -> List[Tuple[int, int, int]]:
    out: List[Tuple[int, int, int]] = []
    width = 2
    while 10 ** width <= limit:
        lo, hi = 10 ** (width - 1), min(10 ** width, limit)
        half_lo, half_hi = 10 ** (width // 2 - 1), 10 ** (width // 2)
        for v in range(lo, hi):
            x = half_lo
            while x * x <= v:
                if v % x == 0:
                    y = v // x
                    if half_lo <= y < half_hi and not (x % 10 == 0 and y % 10 == 0):
                        if is_fang_pair(10, x, y):
                            out.append((v, x, y))
                x += 1
        width += 2
    return out


if __name__ == "__main__":
    for v, x, y in vampires_below(10 ** 6):
        print(f"{v} = {x} * {y}")

