def verify_congruence_laws(b: int, x: int, y: int) -> None:
    """Assert both faces of the vampire law on a confirmed fang pair."""
    assert is_fang_pair(b, x, y), "not a fang pair"
    m = b - 1
    assert (x * y) % m == (x + y) % m, "additive law xy == x+y (mod b-1) failed"
    assert ((x - 1) * (y - 1)) % m == 1 % m, "unit law (x-1)(y-1)==1 (mod b-1) failed"
    if b == 10:
        assert x % 3 != 1 and y % 3 != 1, "a fang was 1 mod 3 (forbidden)"
    print(f"base {b}: ({x},{y}) satisfies xy=x+y and (x-1)(y-1)=1  (mod {m})")


