    return out


def digit_sum(b: int, n: int) -> int:
    return sum(digits(b, n))


def check_casting_out_nines(b: int, upto: int) -> bool:
    """n == digitsum_b(n)  (mod b-1)  for all n < upto."""
    return all((n - digit_sum(b, n)) % (b - 1) == 0 for n in range(upto))


def multifang_law(b: int, factors: List[int]) -> bool:
    """prod(L) == sum(L) (mod b-1) whenever the factors' digits are conserved."""
    prod = 1
    for f in factors:
        prod *= f
    return (prod - sum(factors)) % (b - 1) == 0


