function DIGITAL_ROOT_RESIDUE(b, n):
    if b == 2: return 0            # modulus 1
    return (sum of base-b digits of n) mod (b - 1)

function FANG_PAIR_ADMISSIBLE(b, x, y):
    m  <- b - 1
    rx <- DIGITAL_ROOT_RESIDUE(b, x)
    ry <- DIGITAL_ROOT_RESIDUE(b, y)
    return ((rx - 1) * (ry - 1)) mod m == 1 mod m

